import assert from 'node:assert/strict';import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import {fork} from 'node:child_process';import {fileURLToPath} from 'node:url';
/** options.subjects: a Google subject per profile (default: all three in one account). */
export async function createDproHarness(options={}){
process.env.NODE_ENV='test';const root=fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(),'dpro-runtime-')));process.env.HOME=root;process.env.DATABASE_PATH=path.join(root,'unused.db');process.env.AGENT_PLAYER_CONFIG_DIR=path.join(root,'unused-config');
const {listenAccountService}=await import('../../../account-service/src/server.ts'),{createRelay}=await import('../../../relay/src/relay.ts');
const account=await listenAccountService({databasePath:path.join(root,'server','metadata.db'),epochRoot:path.join(root,'independent-floor'),port:0,initializeNewStore:true,confirmedIndependentRetention:true,temporaryTestOnly:true,secretKey:Buffer.alloc(32,9),verifyGoogle:async(token,_client,nonce)=>{const p=JSON.parse(token);assert.equal(p.nonce,nonce);return {issuer:'https://accounts.google.com',subject:p.subject,verifiedAt:Date.now(),expiresAt:Date.now()+300000};}}),relay=createRelay({port:0}),address=await relay.listen(),relayUrl=`ws://127.0.0.1:${address.port}/v1`,peers=[];
/* Slower CI runners need longer than local runs (seen at 25 s on 2026-11-11); still well under the 120 s test limit. */
const until=async(fn,timeout=60000)=>{const end=Date.now()+timeout;while(Date.now()<end){const v=await fn();if(v)return v;await new Promise(r=>setTimeout(r,80));}throw Error('Dpro temporary fixture timed out'+peers.map((p,i)=>`\n[profile ${i}] `+(p.stderr+p.stdout).slice(-1500)).join(''));};
try{for(let i=0;i<3;i++){const pending=new Map(),profile=path.join(root,'profile-'+i);let n=0;const child=fork(fileURLToPath(new URL('./dpro-profile.mjs',import.meta.url)),[],{execPath:process.execPath,execArgv:['--import','tsx'],env:{...process.env,NODE_ENV:'test',DPRO_FIXTURE_ROOT:root,DPRO_FIXTURE_PROFILE:profile,DPRO_FIXTURE_ORIGIN:account.origin,DPRO_FIXTURE_RELAY:relayUrl,...(options.subjects?.[i]?{DPRO_FIXTURE_SUBJECT:options.subjects[i]}:{}),...(process.env.DPRO_PG_URLS?{AGENT_PLAYER_DB:'postgres',AGENT_PLAYER_PG_URL:process.env.DPRO_PG_URLS.split(',')[i]}:{AGENT_PLAYER_DB:'sqlite'})},stdio:['ignore','pipe','pipe','ipc']});const p={child,ready:false,stderr:'',stdout:'',request:(operation,args={})=>new Promise((resolve,reject)=>{const id=++n,t=setTimeout(()=>{pending.delete(id);reject(Error(operation+' timed out'));},30000);pending.set(id,{resolve:v=>{clearTimeout(t);resolve(v);},reject:e=>{clearTimeout(t);reject(Error(operation+': '+e.message));}});child.send({id,operation,args});})};child.stdout.on('data',b=>p.stdout+=b);child.stderr.on('data',b=>p.stderr+=b);child.on('message',m=>{if(m.event==='ready')p.ready=true;const entry=pending.get(m.id);if(entry){pending.delete(m.id);m.error?entry.reject(Error(m.error)):entry.resolve(m.result);}});child.on('exit',()=>{for(const e of pending.values())e.reject(Error('Profile exited: '+p.stderr));pending.clear();});peers.push(p);await until(()=>p.ready||p.child.exitCode!==null);if(!p.ready)throw Error('Profile startup refused: '+p.stderr);}}catch(error){for(const p of peers){if(p.child.connected)p.child.disconnect();p.child.kill('SIGTERM');}await relay.close();await account.close();throw error;}
const close=async()=>{for(const p of peers){await p.request('stop').catch(()=>{});if(p.child.connected)p.child.disconnect();}await relay.close();await account.close();fs.writeFileSync(path.join(root,'receipt.json'),JSON.stringify({profiles:peers.map(p=>({stderr:p.stderr,stdout:p.stdout})),temporary:true,google:'mock',os:'AES mock, not Keychain/DPAPI',relayStopped:true,accountServiceStopped:true},null,2));};

return {root,account,relay,peers,until,close};}
